/*
 * The one way a step is edited. Only the fields of the step's own kind are written; a field
 * the page did not send is left as it is, and an empty one is cleared.
 *  - Times: the page sends the coach's wall-clock time, "YYYY-MM-DDTHH:MM" (a due date may be
 *    "YYYY-MM-DD", meaning 18:00), read in the coach's zone, Europe/Paris. Stored as ISO.
 *  - A live session with a time is 'booked'; with none it is 'to book'. Done and missed are
 *    left alone (DBU-05 marks those).
 *  - Links are http(s) only. A resource file must already be on this step (copied from the
 *    library) or be one THIS coach uploaded: never a learner's private hand-in.
 *  - Briefs and summaries are Markdown, stored as typed: pages show them only through
 *    Shell/Formatted text, with HTML off.
 *  - A check-in (DBU-10) takes a form by id (a COPY from shared/Checkin forms) and is sent on a
 *    day at 09:00 Paris, or `sendAfter` {step, days}: N days after a live session's day or a
 *    homework's due day in the same plan. Its sendsAt is worked out now, and again whenever that
 *    step's date changes (below); with no date there yet, it has none. Once a check-in is sent,
 *    its form and date stay as they were: the learner may already be answering it.
 * A shared step rings the learner's doorbell, so their page re-reads.
 */
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const R = Noodl.Records;
    const me = String(Inputs.userId || '');
    const id = String(Inputs.id || '');
    const found = id ? await R.query('Step', { objectId: { equalTo: id } }, { limit: 2, plain: true }) : [];
    if (found.length !== 1) return refuse('That step is no longer in the plan. Reload the page.');
    const step = found[0];
    const sent = (k) => Inputs[k] !== undefined && Inputs[k] !== null;
    const text = (k) => String(Inputs[k] || '').replace(/\r\n/g, '\n').trim();

    const TZ = 'Europe/Paris';
    const offsetMs = (utc) => {
      const fmt = new Intl.DateTimeFormat('en-GB', { timeZone: TZ, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' });
      const p = Object.fromEntries(fmt.formatToParts(new Date(utc)).map((x) => [x.type, x.value]));
      return Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute, +p.second) - utc;
    };
    // '' clears; 'YYYY-MM-DD' takes the default hour; 'YYYY-MM-DDTHH:MM' is Paris time; a full ISO time passes.
    const when = (value, defaultHour) => {
      const v = String(value || '').trim();
      if (!v) return null;
      if (v.endsWith('Z') || v.includes('+')) {
        const t = new Date(v);
        return isNaN(t) ? undefined : t.toISOString();
      }
      const [date, time] = v.split('T');
      const [y, m, d] = date.split('-').map(Number);
      const [hh, mm] = (time || defaultHour).split(':').map(Number);
      if (![y, m, d, hh, mm].every(Number.isInteger) || m < 1 || m > 12 || d < 1 || d > 31 || hh > 23 || mm > 59) return undefined;
      const guess = Date.UTC(y, m - 1, d, hh, mm);
      return new Date(guess - offsetMs(guess)).toISOString();
    };
    // A check-in N days after a date: that day in Paris, plus N, at 09:00 Paris. No date, no send date.
    const daysAfter = (iso, days) => {
      if (!iso || isNaN(Date.parse(iso))) return null;
      const [y, m, d] = new Date(iso).toLocaleDateString('en-CA', { timeZone: TZ }).split('-').map(Number);
      const guess = Date.UTC(y, m - 1, d + days, 9, 0);
      return new Date(guess - offsetMs(guess)).toISOString();
    };
    const dateOf = (s) => (s.kind === 'live' ? s.startsAt : s.kind === 'homework' ? s.dueAt : null) || null;
    const link = (k, what) => {
      const v = text(k);
      if (!v) return '';
      let u = null;
      try { u = new URL(v); } catch (e) { u = null; }
      if (!u || (u.protocol !== 'https:' && u.protocol !== 'http:')) { refuse('The ' + what + ' is not a web address. Links start with https://'); return undefined; }
      return u.href;
    };

    const fields = {};
    const title = text('title').replace(/\s+/g, ' ');
    if (!title) return refuse('Give the step a title.');
    if (title.length > 140) return refuse('Keep the title under 140 characters.');
    fields.title = title;

    if (step.kind === 'live') {
      if (sent('startsAt')) {
        const t = when(Inputs.startsAt, '10:00');
        if (t === undefined) return refuse('The date and time could not be read. Pick them again.');
        fields.startsAt = t;
        if (t && step.status === 'to_book') fields.status = 'booked';
        if (!t && step.status === 'booked') fields.status = 'to_book';
      }
      if (sent('durationMin')) {
        const n = Number(String(Inputs.durationMin).trim());
        if (!Number.isInteger(n) || n < 5 || n > 600) return refuse('Give the length as a whole number of minutes, between 5 and 600.');
        fields.durationMin = n;
      }
      if (sent('meetingLink')) { const v = link('meetingLink', 'meeting link'); if (v === undefined) return; fields.meetingLink = v; }
      if (sent('recordingUrl')) { const v = link('recordingUrl', 'recording link'); if (v === undefined) return; fields.recordingUrl = v; }
      if (sent('summary')) {
        const s = text('summary');
        if (s.length > 20000) return refuse('The summary is too long. Keep it under 20,000 characters.');
        fields.summary = s;
      }
    }

    if (step.kind === 'homework') {
      if (sent('dueAt')) {
        const t = when(Inputs.dueAt, '18:00');
        if (t === undefined) return refuse('The due date could not be read. Pick it again.');
        fields.dueAt = t;
      }
      if (sent('brief')) {
        const b = text('brief');
        if (b.length > 20000) return refuse('The brief is too long. Keep it under 20,000 characters, or put the rest in a resource.');
        fields.brief = b;
      }
      if (sent('handInChecklist')) {
        if (!Array.isArray(Inputs.handInChecklist)) return refuse('The hand-in list could not be read. Reload the page and try again.');
        const list = Inputs.handInChecklist
          .map((c) => (typeof c === 'string' ? { text: c, required: true } : { text: String((c && c.text) || ''), required: !(c && c.required === false) }))
          .map((c) => ({ text: c.text.trim().replace(/\s+/g, ' '), required: c.required }))
          .filter((c) => c.text);
        if (list.length > 30) return refuse('Keep the hand-in list to 30 items or fewer.');
        if (list.some((c) => c.text.length > 300)) return refuse('Keep each hand-in item under 300 characters.');
        fields.handInChecklist = list;
      }
      if (sent('resources')) {
        if (!Array.isArray(Inputs.resources)) return refuse('The resources could not be read. Reload the page and try again.');
        if (Inputs.resources.length > 20) return refuse('Keep the resources to 20 or fewer.');
        const onStep = new Set((step.resources || []).filter((r) => r && r.file).map((r) => r.file));
        const resources = [];
        for (const r of Inputs.resources) {
          if (!r || typeof r !== 'object') return refuse('A resource could not be read. Remove it and add it again.');
          const label = String(r.label || '').trim().replace(/\s+/g, ' ');
          if (label.length > 200) return refuse('Keep each resource label under 200 characters.');
          if (r.file) {
            const file = String(r.file);
            if (!onStep.has(file)) {
              const rows = await R.query('_Files', { storedName: { equalTo: file } }, { limit: 2, plain: true });
              const owner = rows.length === 1 ? rows[0].owner : null;
              const ownerId = owner && typeof owner === 'object' ? owner.objectId : owner;
              if (!me || ownerId !== me) return refuse('One of the files is not one you uploaded. Remove it and upload it again.');
            }
            const fileName = String(r.fileName || '').trim();
            resources.push({ label: label || fileName || 'File', file, fileName });
          } else {
            const url = String(r.url || '').trim();
            if (!url && !label) continue;
            let parsed = null;
            try { parsed = new URL(url); } catch (e) { parsed = null; }
            if (!parsed || (parsed.protocol !== 'https:' && parsed.protocol !== 'http:')) return refuse('"' + (url || label) + '" is not a web address. Links start with https://');
            resources.push({ label: label || parsed.hostname, url: parsed.href });
          }
        }
        fields.resources = resources;
      }
    }

    if (step.kind === 'checkin') {
      const open = step.status === 'scheduled';
      const formId = text('formId');
      if (sent('formId') && formId && formId !== (step.form && step.form.id)) {
        if (!open) return refuse('This check-in has already gone out, so its questions can\'t change now.');
        const form = (Array.isArray(Inputs.forms) ? Inputs.forms : []).find((f) => f && f.id === formId);
        if (!form) return refuse('That form is no longer offered. Reload the page.');
        fields.form = form;
      }
      // Once it has gone out, its day is history: the date fields are left as they are.
      if (open && sent('sendAfterStep') && text('sendAfterStep')) {
        const anchorId = text('sendAfterStep');
        if (anchorId === step.objectId) return refuse('A check-in can\'t be sent after itself. Pick a session or a homework.');
        const anchors = await R.query('Step', { objectId: { equalTo: anchorId } }, { limit: 2, plain: true });
        const anchor = anchors.length === 1 && anchors[0].plan === step.plan ? anchors[0] : null;
        if (!anchor) return refuse('That step is no longer in the plan. Reload the page.');
        if (anchor.kind !== 'live' && anchor.kind !== 'homework') return refuse('A check-in is sent after a live session or a homework.');
        const days = Number(text('sendAfterDays'));
        if (!text('sendAfterDays') || !Number.isInteger(days) || days < 0 || days > 365) return refuse('Give the number of days as a whole number, from 0 to 365.');
        fields.sendAfter = { step: anchorId, days };
        fields.sendsAt = daysAfter(dateOf(anchor), days);
      } else if (open && sent('sendsAt')) {
        const t = when(Inputs.sendsAt, '09:00');
        if (t === undefined) return refuse('The send date could not be read. Pick it again.');
        fields.sendsAt = t;
        if (sent('sendAfterStep')) fields.sendAfter = null;
      }
    }

    await R.save(step.objectId, fields, { className: 'Step' });
    const ring = new Set();
    if (step.shared === true) ring.add(step.learner);

    // A check-in sent N days after this step follows its date (DBU-10), while it is still to send.
    // A filter takes one key, so the kind is matched after the query.
    const moved = (step.kind === 'live' && fields.startsAt !== undefined) || (step.kind === 'homework' && fields.dueAt !== undefined);
    if (moved) {
      const date = step.kind === 'live' ? fields.startsAt : fields.dueAt;
      const followers = (await R.query('Step', { plan: { equalTo: step.plan } }, { limit: 1000, plain: true }))
        .filter((c) => c.kind === 'checkin' && c.status === 'scheduled' && c.sendAfter && c.sendAfter.step === step.objectId);
      for (const c of followers) {
        const at = daysAfter(date, Number(c.sendAfter.days) || 0);
        if (at !== (c.sendsAt || null)) {
          await R.save(c.objectId, { sendsAt: at }, { className: 'Step' });
          if (c.shared === true) ring.add(c.learner);
        }
      }
    }
    for (const learner of ring) {
      await R.create('Doorbell', { learner, topic: 'plan' }, { acl: { [learner]: { read: true }, 'role:staff': { read: true } } });
    }
    Outputs.stepId = step.objectId;
    Outputs.done();
  } catch (e) {
    console.error('[dbu:saveStep]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
